mapper.select:
SELECT s.*,
    (SELECT COUNT(1) FROM grade g WHERE g.school_id = s.id AND g.deleted = 0) AS grade_count,
    (SELECT COUNT(1) FROM teacher t WHERE t.school_id = s.id AND t.deleted = 0) AS teacher_count,
    (SELECT COUNT(1) FROM student st WHERE st.school_id = s.id AND st.deleted = 0) AS student_count
FROM school s
WHERE s.deleted = 0

    AND s.name LIKE CONCAT('%', #{query.name}, '%')


    AND s.code = #{query.code}


    AND s.type = #{query.type}


    AND s.province = #{query.province}


    AND s.city = #{query.city}


    AND s.status = #{query.status}

ORDER BY s.sort ASC, s.create_time DESC

SELECT id, name, code FROM school WHERE deleted = 0
AND status = #{status}
ORDER BY sort ASC, create_time DESC
